def f(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    o=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            nbd=[]
            for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni,nj=i+di,j+dj
                if 0<=ni<H and 0<=nj<W: nbd.append(g[ni][nj])
            if g[i][j]==bg: continue
            # noise cell
            ok={c:nbd.count(c) for c in set(nbd) if c!=bg}
            new=None
            for c,k in ok.items():
                if k>=2: new=c; break
            if new is not None: o[i][j]=new
    return o
