            ys=[c[0] for c in comp]; xs=[c[1] for c in comp]
            ys,xs=min(ys),max(ys),min(xs),max(xs)
            full=all(g[y][x]==col for y in range(ys[0],ys[1]+1) for x in range(xs[0],xs[1]+1))
            if len(comp)>=4: res.append((col,(ys[0],xs[0]),(ys[1],xs[1])) if full else None)
    return bg,res
